import "unicode/utf8"

// Reverse returns s with its runes in reverse order. Reversing at the rune level
// preserves multi-byte rune integrity.
func Reverse(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}

