import "sort"

// TopTwo returns the two largest elements of xs without mutating the
// argument. It panics if there are fewer than two elements.
func TopTwo(xs []int) []int {
	if len(xs) < 2 {
		panic("TopTwo: not enough elements")
	}
	sorted := make([]int, len(xs))
	copy(sorted, xs)
	sort.Sort(sort.Reverse(sort.IntSlice(sorted)))
	return sorted[:2]
}

